const raycaster=new THREE.Raycaster(),pointer=new THREE.Vector2();let player={x:0,z:8},selected=null,berryBoost=false,berries=3,balls=12,caught=[],moving={x:0,z:0},sound=true,lastTime=0,toastTimer;
const ballCount=document.querySelector('#ballCount'),questCount=document.querySelector('#questCount'),targetCard=document.querySelector('#targetCard'),hintText=document.querySelector('#hintText');
try{const saved=JSON.parse(localStorage.getItem('meadowQuestSave')||'{}');caught=saved.caught||[];balls=saved.balls??12;berries=saved.berries??3}catch{}
ballCount.textContent=balls;questCount.textContent=`${caught.length} / 4`;
const selectRing=new THREE.Mesh(new THREE.RingGeometry(.72,.86,40),new THREE.MeshBasicMaterial({color:'#fff5a8',transparent:true,opacity:.88,side:THREE.DoubleSide}));selectRing.rotation.x=-Math.PI/2;selectRing.position.y=.035;selectRing.visible=false;scene.add(selectRing);
function toast(msg){const el=document.querySelector('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),1900)}
function chirp(freq=560,duration=.08){if(!sound)return;try{const ctx=new (window.AudioContext||window.webkitAudioContext)(),osc=ctx.createOscillator(),gain=ctx.createGain();osc.type='sine';osc.frequency.value=freq;gain.gain.setValueAtTime(.035,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+duration);osc.connect(gain);gain.connect(ctx.destination);osc.start();osc.stop(ctx.currentTime+duration)}catch{}}
function save(){try{localStorage.setItem('meadowQuestSave',JSON.stringify({caught,balls,berries}))}catch{}}
function setTarget(p){selected=p;if(p){const d=p.userData.pokemon;document.querySelector('#targetIcon').textContent=d.emoji;document.querySelector('#targetName').textContent=d.name;document.querySelector('#targetType').textContent=d.type;document.querySelector('#targetDifficulty').textContent='★'.repeat(d.rarity)+'☆'.repeat(4-d.rarity);targetCard.classList.add('show');hintText.textContent=`${d.name} spotted! Tap THROW to catch it.`;selectRing.visible=true}else{targetCard.classList.remove('show');selectRing.visible=false;hintText.textContent='Look around for a Pokémon to catch!'}}
function pointSelect(event){const rect=renderer.domElement.getBoundingClientRect();pointer.x=(event.clientX-rect.left)/rect.width*2-1;pointer.y=-((event.clientY-rect.top)/rect.height)*2+1;raycaster.setFromCamera(pointer,camera);const hits=raycaster.intersectObjects(creatures.filter(c=>!c.userData.caught).flatMap(c=>c.children),true);if(!hits.length)return;let obj=hits[0].object;while(obj&&!obj.userData.pokemon)obj=obj.parent;if(!obj)return;setTarget(obj);chirp(690,.06)}
renderer.domElement.addEventListener('pointerdown',e=>{if(e.target.closest?.('button'))return;pointSelect(e)});
function updateInventory(){ballCount.textContent=balls;questCount.textContent=`${caught.length} / 4`;save()}
function throwBall(){if(!selected||selected.userData.caught){toast('Tap a wild Pokémon first!');return}if(balls<=0){toast('Out of Poké Balls!');return}balls--;updateInventory();const target=selected,d=target.userData.pokemon;const ball=new THREE.Group();const red=new THREE.Mesh(new THREE.SphereGeometry(.18,16,12),mat('#e64f45'));const lower=new THREE.Mesh(new THREE.SphereGeometry(.18,16,12,0,Math.PI*2,Math.PI/2,Math.PI/2),white);ball.add(red,lower);const band=new THREE.Mesh(new THREE.TorusGeometry(.18,.025,6,16),mat('#324d49'));ball.add(band);const button=blob(ball,'#fff8e6',[0,0,.17],[.065,.065,.025]);ball.position.set(player.x,.9,player.z);scene.add(ball);chirp(440,.1);
 const start=performance.now(),from=ball.position.clone(),to=target.position.clone().add(new THREE.Vector3(0,.8,0));function fly(now){const t=Math.min(1,(now-start)/430);ball.position.lerpVectors(from,to,t);ball.position.y+=Math.sin(t*Math.PI)*2.1;ball.scale.setScalar(1-t*.32);if(t<1){requestAnimationFrame(fly)}else{scene.remove(ball);scene.add(ball);ball.position.copy(to);target.visible=false;const distance=Math.hypot(target.position.x-player.x,target.position.z-player.z),chance=Math.max(.24,Math.min(.94,.83-(d.rarity-1)*.14-distance*.018+(berryBoost?.2:0)));berryBoost=false;setTimeout(()=>{if(Math.random()<chance){caught.push(d.name);target.userData.caught=true;target.visible=false;const burst=new THREE.Mesh(new THREE.SphereGeometry(.25,10,8),new THREE.MeshBasicMaterial({color:'#fff3ae',transparent:true,opacity:.9}));burst.position.copy(to);scene.add(burst);let k=0;const pop=()=>{k++;burst.scale.setScalar(1+k*.45);burst.material.opacity=Math.max(0,1-k/14);if(k<14)requestAnimationFrame(pop);else scene.remove(burst)};pop();setTarget(null);updateInventory();chirp(880,.2);toast(`Gotcha! ${d.name} was caught!`);if(caught.length>=4)setTimeout(showVictory,900)}else{target.visible=true;target.position.x+=Math.random()>.5?.65:-.65;setTarget(null);chirp(190,.16);toast(`${d.name} broke free! Try again!`)}},650)}}requestAnimationFrame(fly)}
function useBerry(){if(!selected){toast('Choose a Pokémon first!');return}if(berries<=0){toast('No berries left!');return}berries--;berryBoost=true;document.querySelector('#berryBtn').innerHTML=`<span class="em">🍓</span>${berries} LEFT`;toast(`A berry made ${selected.userData.pokemon.name} feel safe!`);chirp(740,.1);save()}
function runToTarget(){if(!selected){toast('Tap a Pokémon to approach it!');return}const dx=selected.position.x-player.x,dz=selected.position.z-player.z,len=Math.hypot(dx,dz)||1;player.x+=dx/len*2.7;player.z+=dz/len*2.7;player.x=Math.max(-17,Math.min(17,player.x));player.z=Math.max(-15,Math.min(17,player.z));trainer.position.x=player.x;trainer.position.z=player.z;toast(`You crept closer to ${selected.userData.pokemon.name}!`);chirp(520,.07)}
document.querySelector('#throwBtn').addEventListener('click',throwBall);document.querySelector('#berryBtn').addEventListener('click',useBerry);document.querySelector('#runBtn').addEventListener('click',runToTarget);
function openModal(html){const wrap=document.querySelector('#modalWrap');document.querySelector('#modal').innerHTML=html;wrap.classList.add('open')}
function closeModal(){document.querySelector('#modalWrap').classList.remove('open')}
document.querySelector('#modalWrap').addEventListener('pointerdown',e=>{if(e.target.id==='modalWrap')closeModal()});
document.querySelector('#dexBtn').addEventListener('click',()=>{const entries=pokemonData.map(p=>{const got=caught.includes(p.name);return `<div class="collection-item ${got?'':'empty'}">${got?p.emoji:'❔'}<span>${got?p.name:'???'}</span></div>`}).join('');openModal(`<div class="modal-emoji">📖</div><h1>Meadow Pokédex</h1><p>${caught.length} of 6 Pokémon discovered. Keep exploring the meadow!</p><div class="collection-grid">${entries}</div><button class="modal-btn" id="closeDex">KEEP EXPLORING</button>`);document.querySelector('#closeDex').onclick=closeModal});
document.querySelector('#soundBtn').addEventListener('click',e=>{sound=!sound;e.currentTarget.textContent=sound?'🔊':'🔇';e.currentTarget.classList.toggle('sound-on',!sound);if(sound)chirp(700,.08)});
function showVictory(){openModal(`<div class="modal-emoji">🏆</div><h1>Meadow Champion!</h1><p>You caught four Pokémon and completed your field research. A whole meadow of new friends awaits!</p><div class="collection-grid">${caught.slice(-4).map(n=>{const p=pokemonData.find(x=>x.name===n);return `<div class="collection-item">${p?.emoji||'⭐'}<span>${n}</span></div>`}).join('')}</div><button class="modal-btn" id="victoryClose">KEEP EXPLORING</button>`);document.querySelector('#victoryClose').onclick=closeModal}

