// Soft clouds and a warm sun make the clearing read as a miniature 3D world.
const sunDisc=new THREE.Mesh(new THREE.CircleGeometry(2.1,32),new THREE.MeshBasicMaterial({color:'#fff0b5'}));sunDisc.position.set(-15,15,-32);scene.add(sunDisc);
for(let i=0;i<8;i++){const cloud=new THREE.Group();for(let j=0;j<4;j++){const puff=new THREE.Mesh(new THREE.SphereGeometry(.8+Math.random()*.55,12,10),new THREE.MeshBasicMaterial({color:'#f5fff0',transparent:true,opacity:.73}));puff.position.set(j*.75,.1+(j%2)*.24,0);cloud.add(puff)}cloud.position.set(-24+i*7,12+(i%3)*1.4,-25-Math.random()*12);cloud.scale.setScalar(.7+Math.random()*.5);scene.add(cloud)}
const keys={};window.addEventListener('keydown',e=>{keys[e.key.toLowerCase()]=true;if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(e.key.toLowerCase()))e.preventDefault();if(e.key===' '){throwBall()}});window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
const joystick=document.querySelector('#joystick'),joyKnob=document.querySelector('#joyKnob');let joyPointer=null;
function joyMove(e){if(joyPointer!==e.pointerId)return;const r=joystick.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,dx=e.clientX-cx,dy=e.clientY-cy,lim=r.width*.31,len=Math.hypot(dx,dy),scale=len>lim?lim/len:1;joyKnob.style.left=`calc(50% + ${dx*scale}px)`;joyKnob.style.top=`calc(50% + ${dy*scale}px)`;moving.x=dx*scale/lim;moving.z=dy*scale/lim}
joystick.addEventListener('pointerdown',e=>{joyPointer=e.pointerId;joystick.setPointerCapture(e.pointerId);joyMove(e)});joystick.addEventListener('pointermove',joyMove);function joyEnd(e){if(joyPointer===e.pointerId){joyPointer=null;moving.x=moving.z=0;joyKnob.style.left='50%';joyKnob.style.top='50%'}}joystick.addEventListener('pointerup',joyEnd);joystick.addEventListener('pointercancel',joyEnd);
function frame(now){requestAnimationFrame(frame);const dt=Math.min(.05,(now-lastTime)/1000||0);lastTime=now;let ix=moving.x,iz=moving.z;if(keys.w||keys.arrowup)iz-=1;if(keys.s||keys.arrowdown)iz+=1;if(keys.a||keys.arrowleft)ix-=1;if(keys.d||keys.arrowright)ix+=1;const mag=Math.hypot(ix,iz);if(mag>1){ix/=mag;iz/=mag}player.x+=ix*dt*5.2;player.z+=iz*dt*5.2;player.x=Math.max(-17,Math.min(17,player.x));player.z=Math.max(-17,Math.min(18,player.z));trainer.position.x=player.x;trainer.position.z=player.z;trainer.rotation.y=Math.atan2(ix,iz);
 for(const c of creatures){if(c.userData.caught)continue;const phase=now*.002+c.userData.phase;c.position.y=.045+Math.sin(phase)*.07;c.rotation.y=Math.sin(phase*.55)*.17;c.scale.setScalar(1+Math.sin(phase*1.7)*.018)}
 if(selected&&!selected.userData.caught){selectRing.position.set(selected.position.x,.035,selected.position.z);selectRing.rotation.z=now*.0004;selectRing.scale.setScalar(1+Math.sin(now*.006)*.045)}
 const desired=new THREE.Vector3(player.x,player.z+10.5,player.z+13.5);camera.position.lerp(desired,1-Math.pow(.001,dt));camera.lookAt(player.x,1.1,player.z-2.5);renderer.render(scene,camera)}requestAnimationFrame(frame);
function resize(){camera.aspect=innerWidth/innerHeight;camera.fov=innerWidth<600?48:43;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,2))}window.addEventListener('resize',resize);resize();
</script>
